1	package release
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sync"
10		"syscall"
11	)
12	
13	const (
14		stateFileName = "ledger.json"
15		lockFileName  = "ledger.lock"
16		stateVersion  = 1
17	)
18	
19	// Store 是一个本地配方批次台账，数据保存在调用方指定的目录中。
20	// 不同目录互相独立；多个 Store 可以安全并发提交（进程内互斥、进程间文件锁）。
21	type Store struct {
22		dir      string
23		lockFile *os.File
24		mu       sync.Mutex
25		state    *persistedState
26	}
27	
28	// Open 打开（或首次使用）位于 dir 的台账。
29	// 目录不存在时会创建；目录中没有台账文件时得到空台账；
30	// 已有台账文件无法读取、解析，或任一批次绑定的配方版本未登记时，
31	// 返回 ErrCorruptData（可用 errors.Is 判断），不会当成空台账继续保存，
32	// 也不会返回可继续使用的台账对象。
33	func Open(dir string) (*Store, error) {
34		if dir == "" {
35			return nil, errors.New("数据位置不能为空")
36		}
37		if err := os.MkdirAll(dir, 0o755); err != nil {
38			return nil, fmt.Errorf("创建数据位置 %q 失败: %w", dir, err)
39		}
40		info, err := os.Stat(dir)
41		if err != nil {
42			return nil, fmt.Errorf("读取数据位置 %q 失败: %w", dir, err)
43		}
44		if !info.IsDir() {
45			return nil, fmt.Errorf("数据位置 %q 不是目录", dir)
46		}
47	
48		lockPath := filepath.Join(dir, lockFileName)
49		lf, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
50		if err != nil {
51			return nil, fmt.Errorf("打开锁文件失败: %w", err)
52		}
53	
54		s := &Store{dir: dir, lockFile: lf}
55		if err := s.load(); err != nil {
56			lf.Close()
57			return nil, err
58		}
59		return s, nil
60	}
61	
62	// Close 释放台账占用的文件锁。
63	func (s *Store) Close() error {
64		s.mu.Lock()
65		defer s.mu.Unlock()
66		if s.lockFile == nil {
67			return nil
68		}
69		err := s.lockFile.Close()
70		s.lockFile = nil
71		return err
72	}
73	
74	func (s *Store) lockExclusive() error {
75		if s.lockFile == nil {
76			return errors.New("台账已关闭")
77		}
78		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_EX); err != nil {
79			return fmt.Errorf("锁定台账失败: %w", err)
80		}
81		return nil
82	}
83	
84	func (s *Store) lockShared() error {
85		if s.lockFile == nil {
86			return errors.New("台账已关闭")
87		}
88		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_SH); err != nil {
89			return fmt.Errorf("锁定台账失败: %w", err)
90		}
91		return nil
92	}
93	
94	func (s *Store) unlock() {
95		_ = syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_UN)
96	}
97	
98	func (s *Store) load() error {
99		data, err := os.ReadFile(filepath.Join(s.dir, stateFileName))
100		if err != nil {
101			if os.IsNotExist(err) {
102				s.state = &persistedState{Version: stateVersion, Requests: map[string]*requestRecord{}}
103				return nil
104			}
105			return fmt.Errorf("%w: 读取台账文件失败: %v", ErrCorruptData, err)
106		}
107		if len(data) == 0 {
108			s.state = &persistedState{Version: stateVersion, Requests: map[string]*requestRecord{}}
109			return nil
110		}
111		var st persistedState
112		if err := json.Unmarshal(data, &st); err != nil {
113			return fmt.Errorf("%w: 台账文件解析失败: %v", ErrCorruptData, err)
114		}
115		if st.Version != stateVersion {
116			return fmt.Errorf("%w: 台账版本 %d 不受支持", ErrCorruptData, st.Version)
117		}
118		if err := validateState(&st); err != nil {
119			return err
120		}
121		if st.Requests == nil {
122			st.Requests = map[string]*requestRecord{}
123		}
124		s.state = &st
125		return nil
126	}
127	
128	// validateState 检查台账的引用完整性：每个批次记录的配方编号与版本号
129	// 必须共同指向一个已登记的配方版本。任一批次找不到对应版本，整份台账
130	// 即视为损坏——不能改用同编号的其他版本，也不能按名称或物料内容替换，
131	// 即使其他批次仍然完整也不能放行本次读取。
132	func validateState(st *persistedState) error {
133		for _, b := range st.Batches {
134			if b == nil {
135				return fmt.Errorf("%w: 台账中存在空的批次记录", ErrCorruptData)
136			}
137			if findRecipe(st, b.RecipeNo, b.RecipeVersion) == nil {
138				return fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
139					ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
140			}
141		}
142		return nil
143	}
144	
145	// persist 先写临时文件再原子改名，并 fsync 目录，保证已提交数据可恢复。
146	func (s *Store) persist(st *persistedState) error {
147		data, err := json.MarshalIndent(st, "", "  ")
148		if err != nil {
149			return err
150		}
151		tmpPath := filepath.Join(s.dir, stateFileName+".tmp")
152		f, err := os.OpenFile(tmpPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
153		if err != nil {
154			return err
155		}
156		if _, err := f.Write(data); err != nil {
157			f.Close()
158			return err
159		}
160		if err := f.Sync(); err != nil {
161			f.Close()
162			return err
163		}
164		if err := f.Close(); err != nil {
165			return err
166		}
167		if err := os.Rename(tmpPath, filepath.Join(s.dir, stateFileName)); err != nil {
168			return err
169		}
170		if d, err := os.Open(s.dir); err == nil {
171			_ = d.Sync()
172			_ = d.Close()
173		}
174		return nil
175	}
176	
177	func cloneState(st *persistedState) (*persistedState, error) {
178		data, err := json.Marshal(st)
179		if err != nil {
180			return nil, err
181		}
182		var out persistedState
183		if err := json.Unmarshal(data, &out); err != nil {
184			return nil, err
185		}
186		if out.Requests == nil {
187			out.Requests = map[string]*requestRecord{}
188		}
189		return &out, nil
190	}
191	
192	// write 是所有写入操作的统一入口：
193	//   - reqNo 为空直接报错；
194	//   - 同一 reqNo 且操作与内容完全相同，返回第一次成功的结果（幂等重放）；
195	//   - 同一 reqNo 用于其他操作或不同内容，返回 ErrRequestConflict；
196	//   - apply 在状态副本上执行，返回校验错误时不落盘、不占用请求编号；
197	//   - apply 成功后，状态与请求记录一起原子落盘，再切换到内存状态。
198	func (s *Store) write(reqNo, op string, payload any, apply func(*persistedState) (json.RawMessage, error), out any) error {
199		if reqNo == "" {
200			return errors.New("请求编号不能为空")
201		}
202		s.mu.Lock()
203		defer s.mu.Unlock()
204		if err := s.lockExclusive(); err != nil {
205			return err
206		}
207		defer s.unlock()
208	
209		// 跨进程场景下，其他进程可能已提交新数据；加锁后重新加载，
210		// 确保在最新状态上应用变更，避免用旧快照覆盖其他进程的写入。
211		if err := s.load(); err != nil {
212			return err
213		}
214	
215		payloadRaw, err := json.Marshal(payload)
216		if err != nil {
217			return err
218		}
219		payloadStr := string(payloadRaw)
220	
221		if req, ok := s.state.Requests[reqNo]; ok {
222			if req.Op != op || req.Payload != payloadStr {
223				return fmt.Errorf("%w: 请求编号 %q 已用于操作 %q，不能再用于操作 %q 或不同内容",
224					ErrRequestConflict, reqNo, req.Op, op)
225			}
226			if err := json.Unmarshal(req.Result, out); err != nil {
227				return fmt.Errorf("重放请求 %q 的结果失败: %w", reqNo, err)
228			}
229			return nil
230		}
231	
232		clone, err := cloneState(s.state)
233		if err != nil {
234			return err
235		}
236		result, err := apply(clone)
237		if err != nil {
238			return err
239		}
240		clone.Requests[reqNo] = &requestRecord{Op: op, Payload: payloadStr, Result: result}
241		if err := s.persist(clone); err != nil {
242			return fmt.Errorf("保存台账失败: %w", err)
243		}
244		s.state = clone
245		if err := json.Unmarshal(result, out); err != nil {
246			return fmt.Errorf("解析请求结果失败: %w", err)
247		}
248		return nil
249	}
250	
251	// read 在共享锁下读取当前状态。
252	func (s *Store) read(fn func(*persistedState) error) error {
253		s.mu.Lock()
254		defer s.mu.Unlock()
255		if err := s.lockShared(); err != nil {
256			return err
257		}
258		defer s.unlock()
259		if err := s.load(); err != nil {
260			return err
261		}
262		return fn(s.state)
263	}
264	
265	// 视图构造：每次都从记录全新构造，返回的切片与内部状态完全隔离。
266	
267	func buildRecipeView(r *recipeRecord) *RecipeView {
268		mats := make([]MaterialView, 0, len(r.Materials))
269		for _, m := range r.Materials {
270			mats = append(mats, MaterialView{MaterialNo: m.MaterialNo, Grams: m.GramsMilli.String()})
271		}
272		return &RecipeView{RecipeNo: r.RecipeNo, Version: r.Version, Name: r.Name, Materials: mats}
273	}
274	
275	func buildBatchView(b *batchRecord, r *recipeRecord) (*BatchView, error) {
276		v := &BatchView{
277			BatchNo:         b.BatchNo,
278			RecipeNo:        r.RecipeNo,
279			RecipeVersion:   r.Version,
280			RecipeName:      r.Name,
281			PlannedPortions: b.PlannedPortions,
282			Status:          b.Status,
283			Feedings:        make([]FeedingView, 0, len(b.Feedings)),
284			Materials:       make([]MaterialRequirement, 0, len(r.Materials)),
285		}
286	
287		for _, f := range b.Feedings {
288			v.Feedings = append(v.Feedings, FeedingView{
289				Seq:        f.Seq,
290				MaterialNo: f.MaterialNo,
291				Grams:      f.GramsMilli.String(),
292				Time:       f.Time,
293				Registrar:  f.Registrar,
294			})
295		}
296	
297		for _, m := range r.Materials {
298			required, err := multiplyPortions(m.GramsMilli, b.PlannedPortions)
299			if err != nil {
300				return nil, fmt.Errorf("批次 %q 数量核对失败: %w", b.BatchNo, err)
301			}
302			act, ok := sumMaterialGrams(b, m.MaterialNo)
303			if !ok {
304				return nil, fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出可表示范围",
305					ErrCorruptData, b.BatchNo, m.MaterialNo)
306			}
307			v.Materials = append(v.Materials, MaterialRequirement{
308				MaterialNo:      m.MaterialNo,
309				RequiredGrams:   required.String(),
310				ActualGrams:     act.String(),
311				DifferenceGrams: (act - required).String(),
312			})
313		}
314		return v, nil
315	}
316	
317	func findRecipe(st *persistedState, recipeNo, version string) *recipeRecord {
318		for _, r := range st.Recipes {
319			if r.RecipeNo == recipeNo && r.Version == version {
320				return r
321			}
322		}
323		return nil
324	}
325	
326	func findBatch(st *persistedState, batchNo string) *batchRecord {
327		for _, b := range st.Batches {
328			if b.BatchNo == batchNo {
329				return b
330			}
331		}
332		return nil
333	}
334	
335	// sumMaterialGrams 统计批次内某物料已登记投料的累计千分之一克数。
336	// 仅统计该物料的记录，其他物料不参与；返回 ok=false 表示仅已有记录
337	// 的合计就已经超过可表示上限（AddFeeding 的登记前校验会阻止这种状态，
338	// 这里仍防一手整数回绕）。
339	func sumMaterialGrams(b *batchRecord, materialNo string) (sum gramsMilli, ok bool) {
340		for _, f := range b.Feedings {
341			if f.MaterialNo != materialNo {
342				continue
343			}
344			if f.GramsMilli > maxGramsMilli-sum {
345				return maxGramsMilli, false
346			}
347			sum += f.GramsMilli
348		}
349		return sum, true
350	}
