1	package release
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"time"
7	)
8	
9	const (
10		opCreateBatch = "createBatch"
11		opUpdateDraft = "updateDraftBatch"
12		opStartBatch  = "startBatch"
13		opCloseBatch  = "closeBatch"
14		opAddFeeding  = "addFeeding"
15	)
16	
17	type createBatchPayload struct {
18		BatchNo  string
19		RecipeNo string
20		Version  string
21		Portions int
22	}
23	
24	type updateDraftPayload struct {
25		BatchNo  string
26		RecipeNo string // 留空表示不改配方
27		Version  string // 与 RecipeNo 同时给出
28		Portions int    // 0 表示不改份数
29	}
30	
31	type startBatchPayload struct {
32		BatchNo string
33	}
34	
35	type closeBatchPayload struct {
36		BatchNo string
37	}
38	
39	type addFeedingPayload struct {
40		BatchNo    string
41		MaterialNo string
42		Grams      string
43		Time       time.Time
44		Registrar  string
45	}
46	
47	// CreateBatch 创建批次。
48	// 批次使用独立批次编号，选择已登记的配方版本和计划份数（必须为正整数）。
49	// 新批次为草稿；批次编号重复、配方版本不存在或数量不合法时返回具体原因且不保留数据。
50	func (s *Store) CreateBatch(reqNo, batchNo, recipeNo, version string, portions int) (*BatchView, error) {
51		payload := createBatchPayload{BatchNo: batchNo, RecipeNo: recipeNo, Version: version, Portions: portions}
52		var out BatchView
53		err := s.write(reqNo, opCreateBatch, payload, func(st *persistedState) (json.RawMessage, error) {
54			if batchNo == "" {
55				return nil, fmt.Errorf("%w: 批次编号不能为空", ErrInvalidInput)
56			}
57			if portions <= 0 {
58				return nil, fmt.Errorf("%w: 计划份数必须为正整数，得到 %d", ErrInvalidInput, portions)
59			}
60			if findBatch(st, batchNo) != nil {
61				return nil, fmt.Errorf("%w: 批次 %q 已存在", ErrDuplicateBatch, batchNo)
62			}
63			r := findRecipe(st, recipeNo, version)
64			if r == nil {
65				return nil, fmt.Errorf("%w: 配方 %q 版本 %q 不存在", ErrNotFound, recipeNo, version)
66			}
67			b := &batchRecord{
68				BatchNo:         batchNo,
69				RecipeNo:        recipeNo,
70				RecipeVersion:   version,
71				PlannedPortions: portions,
72				Status:          StatusDraft,
73			}
74			view, err := buildBatchView(b, r)
75			if err != nil {
76				return nil, err
77			}
78			raw, err := json.Marshal(view)
79			if err != nil {
80				return nil, err
81			}
82			st.Batches = append(st.Batches, b)
83			return raw, nil
84		}, &out)
85		if err != nil {
86			return nil, err
87		}
88		return &out, nil
89	}
90	
91	// UpdateDraftBatch 调整草稿批次的计划份数或改选配方版本。
92	// newRecipeNo/newVersion 都留空表示不改配方；newPortions 传 0 表示不改份数。
93	// 只有草稿状态可以调整；开始执行后两者固定。
94	func (s *Store) UpdateDraftBatch(reqNo, batchNo, newRecipeNo, newVersion string, newPortions int) (*BatchView, error) {
95		payload := updateDraftPayload{BatchNo: batchNo, RecipeNo: newRecipeNo, Version: newVersion, Portions: newPortions}
96		var out BatchView
97		err := s.write(reqNo, opUpdateDraft, payload, func(st *persistedState) (json.RawMessage, error) {
98			b := findBatch(st, batchNo)
99			if b == nil {
100				return nil, fmt.Errorf("%w: 批次 %q", ErrNotFound, batchNo)
101			}
102			if b.Status != StatusDraft {
103				return nil, fmt.Errorf("%w: 批次 %q 状态为 %s，只有草稿可以调整", ErrInvalidState, batchNo, b.Status)
104			}
105			if newPortions != 0 {
106				if newPortions <= 0 {
107					return nil, fmt.Errorf("%w: 计划份数必须为正整数，得到 %d", ErrInvalidInput, newPortions)
108				}
109				b.PlannedPortions = newPortions
110			}
111			if newRecipeNo != "" || newVersion != "" {
112				if newRecipeNo == "" || newVersion == "" {
113					return nil, fmt.Errorf("%w: 改选配方版本时必须同时给出配方编号和版本号", ErrInvalidInput)
114				}
115				r := findRecipe(st, newRecipeNo, newVersion)
116				if r == nil {
117					return nil, fmt.Errorf("%w: 配方 %q 版本 %q 不存在", ErrNotFound, newRecipeNo, newVersion)
118				}
119				b.RecipeNo = newRecipeNo
120				b.RecipeVersion = newVersion
121			}
122			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
123			if r == nil {
124				return nil, fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
125					ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
126			}
127			view, err := buildBatchView(b, r)
128			if err != nil {
129				return nil, err
130			}
131			raw, err := json.Marshal(view)
132			if err != nil {
133				return nil, err
134			}
135			return raw, nil
136		}, &out)
137		if err != nil {
138			return nil, err
139		}
140		return &out, nil
141	}
142	
143	// StartBatch 开始执行批次：草稿 → 执行中。
144	// 开始后计划份数与配方版本固定，只有执行中的批次可以关闭。
145	func (s *Store) StartBatch(reqNo, batchNo string) (*BatchView, error) {
146		payload := startBatchPayload{BatchNo: batchNo}
147		var out BatchView
148		err := s.write(reqNo, opStartBatch, payload, func(st *persistedState) (json.RawMessage, error) {
149			b := findBatch(st, batchNo)
150			if b == nil {
151				return nil, fmt.Errorf("%w: 批次 %q", ErrNotFound, batchNo)
152			}
153			if b.Status != StatusDraft {
154				return nil, fmt.Errorf("%w: 批次 %q 状态为 %s，只有草稿可以开始执行", ErrInvalidState, batchNo, b.Status)
155			}
156			b.Status = StatusExecuting
157			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
158			if r == nil {
159				return nil, fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
160					ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
161			}
162			view, err := buildBatchView(b, r)
163			if err != nil {
164				return nil, err
165			}
166			raw, err := json.Marshal(view)
167			if err != nil {
168				return nil, err
169			}
170			return raw, nil
171		}, &out)
172		if err != nil {
173			return nil, err
174		}
175		return &out, nil
176	}
177	
178	// CloseBatch 关闭批次：执行中 → 已关闭。
179	// 关闭表示确认已有投料，不要求数量已经吻合；
180	// 关闭后不能追加投料，也不能重新打开。
181	func (s *Store) CloseBatch(reqNo, batchNo string) (*BatchView, error) {
182		payload := closeBatchPayload{BatchNo: batchNo}
183		var out BatchView
184		err := s.write(reqNo, opCloseBatch, payload, func(st *persistedState) (json.RawMessage, error) {
185			b := findBatch(st, batchNo)
186			if b == nil {
187				return nil, fmt.Errorf("%w: 批次 %q", ErrNotFound, batchNo)
188			}
189			if b.Status != StatusExecuting {
190				return nil, fmt.Errorf("%w: 批次 %q 状态为 %s，只有执行中的批次可以关闭", ErrInvalidState, batchNo, b.Status)
191			}
192			b.Status = StatusClosed
193			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
194			if r == nil {
195				return nil, fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
196					ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
197			}
198			view, err := buildBatchView(b, r)
199			if err != nil {
200				return nil, err
201			}
202			raw, err := json.Marshal(view)
203			if err != nil {
204				return nil, err
205			}
206			return raw, nil
207		}, &out)
208		if err != nil {
209			return nil, err
210		}
211		return &out, nil
212	}
213	
214	// AddFeeding 向执行中的批次追加一次投料。
215	// 投料包含物料编号、克数（正数、最多三位小数）、投料时间和登记人；
216	// 物料必须属于该批次绑定的配方版本。允许实际投料不足或超过应投量；
217	// 已登记的投料不能修改或删除，关闭后也不能追加。
218	// 同一批次内每种物料的累计实投量（仅按该物料统计）上限为
219	// 9223372036854775.807 克，本次投料后恰好等于上限仍允许，超过则返回
220	// ErrInvalidInput 且不保存本次投料。
221	// 投料按成功登记的先后顺序编号，不按投料时间重排。
222	func (s *Store) AddFeeding(reqNo, batchNo, materialNo, grams string, t time.Time, registrar string) (*FeedingView, error) {
223		payload := addFeedingPayload{
224			BatchNo:    batchNo,
225			MaterialNo: materialNo,
226			Grams:      grams,
227			Time:       t,
228			Registrar:  registrar,
229		}
230		var out FeedingView
231		err := s.write(reqNo, opAddFeeding, payload, func(st *persistedState) (json.RawMessage, error) {
232			if materialNo == "" {
233				return nil, fmt.Errorf("%w: 物料编号不能为空", ErrInvalidInput)
234			}
235			if registrar == "" {
236				return nil, fmt.Errorf("%w: 登记人不能为空", ErrInvalidInput)
237			}
238			milli, err := parseGrams(grams)
239			if err != nil {
240				return nil, fmt.Errorf("%w: 物料 %q 的克数: %v", ErrInvalidInput, materialNo, err)
241			}
242			b := findBatch(st, batchNo)
243			if b == nil {
244				return nil, fmt.Errorf("%w: 批次 %q", ErrNotFound, batchNo)
245			}
246			if b.Status != StatusExecuting {
247				return nil, fmt.Errorf("%w: 批次 %q 状态为 %s，只有执行中的批次可以投料", ErrInvalidState, batchNo, b.Status)
248			}
249			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
250			if r == nil {
251				return nil, fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
252					ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
253			}
254			belongs := false
255			for _, m := range r.Materials {
256				if m.MaterialNo == materialNo {
257					belongs = true
258					break
259				}
260			}
261			if !belongs {
262				return nil, fmt.Errorf("%w: 物料 %q 不在配方 %q 版本 %q 中",
263					ErrMaterialNotInRecipe, materialNo, r.RecipeNo, r.Version)
264			}
265	
266			// 上限按物料分别判断：只累计该物料已登记的投料，
267			// 其他物料的投料量不参与，也不互相抵消。
268			summed, ok := sumMaterialGrams(b, materialNo)
269			if !ok || summed > maxGramsMilli-milli {
270				return nil, fmt.Errorf("%w: 物料 %q 的数量超出范围：本次投料后累计实投将超过上限 %s 克",
271					ErrInvalidInput, materialNo, maxGramsMilli)
272			}
273	
274			seq := len(b.Feedings) + 1
275			rec := feedingRecord{
276				Seq:        seq,
277				MaterialNo: materialNo,
278				GramsMilli: milli,
279				Time:       t,
280				Registrar:  registrar,
281			}
282			view := FeedingView{
283				Seq:        seq,
284				MaterialNo: materialNo,
285				Grams:      milli.String(),
286				Time:       t,
287				Registrar:  registrar,
288			}
289			raw, err := json.Marshal(view)
290			if err != nil {
291				return nil, err
292			}
293			b.Feedings = append(b.Feedings, rec)
294			return raw, nil
295		}, &out)
296		if err != nil {
297			return nil, err
298		}
299		return &out, nil
300	}
301	
302	// GetBatch 按批次编号查询，返回未找到（ErrNotFound）时表示批次不存在。
303	// 返回内容包含所用配方版本、计划份数、状态、全部投料（登记顺序），
304	// 以及按物料逐项的应投量、累计实投量和差额；无投料的物料也会列出。
305	// 返回的视图是台账数据的副本，调用方修改不会影响台账。
306	func (s *Store) GetBatch(batchNo string) (*BatchView, error) {
307		var out *BatchView
308		err := s.read(func(st *persistedState) error {
309			b := findBatch(st, batchNo)
310			if b == nil {
311				return fmt.Errorf("%w: 批次 %q", ErrNotFound, batchNo)
312			}
313			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
314			if r == nil {
315				return fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 不存在",
316					ErrCorruptData, batchNo, b.RecipeNo, b.RecipeVersion)
317			}
318			view, err := buildBatchView(b, r)
319			if err != nil {
320				return err
321			}
322			out = view
323			return nil
324		})
325		if err != nil {
326			return nil, err
327		}
328		return out, nil
329	}
