	if err := json.Unmarshal(good, &broken); err != nil {
		t.Fatal(err)
	}
	for _, b := range broken.Batches {
		if b.BatchNo == "B1" {
			b.Feedings = append(b.Feedings, feedingRecord{
				Seq: 1, MaterialNo: "M1", GramsMilli: -1, Time: fixedTime, Registrar: "张三",
			})
		}
	}
